//! Input assembly of the daily sleep and readiness scores. See `docs/algorithms/metrics.md`;
//! the vectors in the tests are generated by `tools/gen_public_vectors_readiness.py`.
//!
//! [`readiness`](super::readiness) holds the arithmetic (`readiness_calculate`, `recovery_run`)
//! and [`sleep_score`](super::sleep_score) the sleep score combiner; this module builds their
//! arguments from the day's sleep periods.
//! The day is processed prefix by prefix: for k = 1..n the first k periods are scored
//! ([`get_daily_sleep`], then [`daily_readiness_stateless`]). The last prefix supplies every
//! output field except the sleep score, which [`final_sleep_score`] derives from the prefix
//! scores.
//!
//! Sleep period record: `is_main`, the bedtime start (Unix seconds), the time zone offset in minutes,
//! then u32 fields in the order of [`SleepPeriod`].

use super::readiness::{
    readiness_calculate, recovery_run, Features, ReadinessInput, ReadinessOutput, ReadinessV2Input,
    RestMode, Session, SleepSummary, State, MISSING,
};
use super::sleep_score::{curve, timing_score, WEIGHTS};

/// Periods starting before 1354757888 (2012-12-06) are ignored, and so are those starting
/// `TIME_SPAN` seconds (to 2049) after it.
const TIME_LO: i64 = -0x50B7_F700;
const TIME_SPAN: u64 = 0x4598_4F01;

/// the sleep period record (the fields the daily functions read).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct SleepPeriod {
    pub is_main: u32,
    pub start: i64,
    pub tz: i32,
    pub time_in_bed: u32,
    pub total_sleep: u32,
    pub rem: u32,
    pub deep: u32,
    pub efficiency: u32,
    pub latency: u32,
    pub wake_ups: u32,
    pub restless: u32,
    pub got_up: u32,
    /// Sleep midpoint in 30-second epochs after the start.
    pub midpoint: u32,
    pub highest_temp: u32,
    pub lowest_hr: u32,
    pub lowest_hr_time: u32,
    pub rmssd: u32,
}

/// the daily sleep output record: score, the seven contributors (total sleep, deep, REM,
/// efficiency, latency, disturbances, circadian alignment), the total sleep sum (s), and the
/// night values the readiness step adds.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct DailySleep {
    pub score: u32,
    pub contributors: [u32; 7],
    pub total_sleep_sum: u32,
    pub highest_temp: u32,
    pub lowest_hr: u32,
    pub lowest_hr_time: u32,
    pub rmssd: u32,
}

/// the readiness history record; arrays are newest first.
#[derive(Clone, Debug, Default)]
pub struct History {
    pub temp_dev_3: Option<[i32; 3]>,
    pub hot_90: Option<Vec<u32>>,
    pub sleep_sec_14: Option<[u32; 14]>,
    pub distance_14: Option<[u32; 14]>,
    pub rmssd_14: Option<[u32; 14]>,
    pub wear_14: Option<[u8; 14]>,
}

/// The day-level inputs shared by the readiness functions. `user` is the first two words of
/// the user info record (the second is the age in years); `prev_day` the 8 words of
/// the previous-day input record; `baseline` the baseline record; `rest_input` is
/// `(start, end, unused, current midnight)`.
#[derive(Clone, Debug, Default)]
pub struct DayData {
    pub prev_day: Option<[u32; 8]>,
    pub user: Option<(u32, u32)>,
    pub history: History,
    pub baseline: Option<[u8; 0x38]>,
    pub day_number: u32,
    pub cycle_day_type: u8,
    pub rest_input: Option<(i64, i64, i64, i64)>,
}

fn valid_time(t: i64) -> bool {
    (t as u64).wrapping_add(TIME_LO as u64) < TIME_SPAN
}

/// `(x + 30) / 60` on u32 (a multiply-shift reciprocal).
fn div60r(x: u32) -> u32 {
    x.wrapping_add(30) / 60
}

// ---------------------------------------------------------------------------- sleep score v1

const STATIC: [[i64; 4]; 6] = [
    [30, 60, 90, 95],
    [60, 28, 2, 0],
    [240, 128, 16, 0],
    [80, 50, 25, 15],
    [96, 48, 16, 0],
    [390, 240, 100, 90],
];

/// Knots of rows 0..2 (total, deep, REM) built from the age (version 1 of the limits).
fn limits_v1(age: u32) -> [[i64; 4]; 3] {
    let a = (age & 0xFF) as i64;
    let total_knot = 0x1E6 - ((a * 0x1C5) >> 8);
    let r = (0x72 - ((a * 0x155) >> 9)).max(60);
    let m = (0x6D - ((a * 0x117) >> 8)).max(20);
    let top = if a < 31 { (total_knot * 5 + 2) >> 2 } else { 0x21C };
    [
        [0, (total_knot + 1) >> 1, (total_knot * 0x12E + 0x80) >> 8, top],
        [0, (m * 0x54 + 0x80) >> 8, (m * 0x12E + 0x80) >> 8, 150],
        [0, (r * 0x54 + 0x80) >> 8, (r * 0x131 + 0x80) >> 8, 150],
    ]
}

fn div_unsigned(a: i64, b: i64) -> i64 {
    if b == 0 {
        0
    } else {
        a / b
    }
}

fn fix(c: i64) -> u32 {
    (if c == 0 {
        1
    } else if c >= 101 {
        100
    } else {
        c
    }) as u32
}

/// Sleep score from minutes with the version 1 knot table. Arguments
/// as in `tools/sleep_score.py` `sleep_score_minutes`; returns (7 contributors, total).
#[allow(clippy::too_many_arguments)]
fn score_minutes(
    age: u32,
    total: u32,
    deep: u32,
    rem: u32,
    eff: u32,
    lat: u32,
    rest: u32,
    tosses: u32,
    ext: u32,
    mid: i16,
    day: u8,
    reference: i32,
) -> ([u32; 7], u32) {
    let a = (total & 0xFFFF) as i64;
    let inputs = [
        a,
        (deep & 0xFFFF) as i64,
        (rem & 0xFFFF) as i64,
        (eff & 0xFF) as i64,
        (lat & 0xFF) as i64,
        (rest & 0xFF) as i64,
        div_unsigned((tosses & 0xFFFF) as i64 * 50 + (a >> 1), a) & 0xFFFF,
        (ext & 0xFF) as i64,
        (mid as i64 - 90).abs(),
    ];
    let l = limits_v1(age);
    let rows = [
        l[0], l[1], l[2], STATIC[0], STATIC[1], STATIC[2], STATIC[3], STATIC[4], STATIC[5],
    ];
    let mut acc = 0i64;
    let mut out = [0i64; 9];
    for i in 0..9 {
        let mut c = if i == 8 && day != 0xFF {
            timing_score(day, reference as f32, mid as f32).round() as i64
        } else {
            curve(inputs[i] & 0xFFFF, &rows[i])
        };
        acc += c * WEIGHTS[i];
        c = c.clamp(0, 100);
        if (5..=7).contains(&i) {
            c = (((2 * c + 3) & 0xFF) * 171) >> 10;
        }
        out[i] = c;
    }
    let total = if acc + 50 < (1 << 32) {
        ((acc + 50) * 0x51EB_851F) >> 37
    } else {
        (acc + 50) / 100
    };
    (
        [
            fix(out[0]),
            fix(out[1]),
            fix(out[2]),
            fix(out[3]),
            fix(out[4]),
            fix(out[5] + out[6] + out[7]),
            fix(out[8]),
        ],
        total as u32,
    )
}

// ---------------------------------------------------------------------------- get_daily_sleep

struct Acc {
    tot: u32,
    deep: u32,
    rem: u32,
    ext: u32,
    eff: u32,
    wake: u32,
    tosses: u32,
}

fn abs_lat(latency: u32) -> u32 {
    let lat = (latency as i32).wrapping_sub(900);
    (if lat >= 0 {
        lat
    } else {
        900i32.wrapping_sub(latency as i32)
    }) as u32
}

/// The daily sleep output ([`get_daily_sleep`]): `age` is
/// the user-info word at +4; `chrono_type` is 0xFF without a chronotype. All zero when no
/// period scores.
///
/// Each period whose midpoint (start + tz * 60 + midpoint * 30) is in the valid range is scored
/// alone; several valid periods are recomputed on the running sums (see the module docs of
/// `tools/readiness_inputs.py`).
pub fn get_daily_sleep(
    age: u32,
    chrono_type: u8,
    chrono_mid: i32,
    periods: &[SleepPeriod],
) -> DailySleep {
    let n = periods.len() as u32;
    let mut s_total = 0u32;
    let mut main_idx = 0usize;
    let mut inv = 0u32;
    let mut day_score = 0u32;
    let mut weighted = 0u32;
    let mut acc: Option<Acc> = None;
    let mut summary = [0u32; 7];
    let mut contrib6 = 0u32;
    for (i, p) in periods.iter().enumerate() {
        let t = p
            .start
            .wrapping_add((p.tz as i64).wrapping_mul(60))
            .wrapping_add(p.midpoint.wrapping_mul(30) as i64);
        if !valid_time(t) {
            inv += 1;
            continue;
        }
        let secs = t.rem_euclid(86400) as i32;
        let (hour, minute, second) = (secs / 3600, (secs % 3600) / 60, secs % 60);
        let mins = if hour < 10 {
            hour * 60
        } else {
            -(24 - hour) * 60
        };
        let sod = (mins + minute) * 60 + second;
        let mut mid_s = sod.wrapping_add(30);
        if p.is_main == 1 {
            main_idx = i;
        } else {
            let a = sod.wrapping_sub(5400).wrapping_abs();
            let b = sod.wrapping_sub(48600).wrapping_abs();
            let c = sod.wrapping_add(37800);
            let c = if c >= 0 {
                c
            } else {
                (-37800i32).wrapping_sub(sod)
            };
            if !(a < c && a < b) {
                mid_s = sod.wrapping_add(if c < b { 0xA8DE } else { -0xA8A2 });
            }
        }
        let (tot, rem, deep, eff) = (p.total_sleep, p.rem, p.deep, p.efficiency);
        let wake_s = p.wake_ups.wrapping_mul(0x1A40);
        let got_up_s = p.got_up.wrapping_mul(0x1A40);
        let tot_min = tot / 60;
        let eff_sum = eff.wrapping_mul(tot_min);
        let restless_sum = p.restless.wrapping_mul(tot_min);
        let (eff_avg, wake_avg, restless_avg, ext) = if tot >= 60 {
            (eff_sum / tot_min, wake_s / tot_min, restless_sum / tot_min, got_up_s / tot_min)
        } else {
            (0, 0, 0, 0)
        };
        s_total = s_total.wrapping_add(tot);
        let (c, sc) = score_minutes(
            age,
            div60r(tot),
            div60r(deep),
            div60r(rem),
            eff_avg,
            div60r(abs_lat(p.latency)),
            wake_avg,
            restless_avg,
            ext & 0xFF,
            (mid_s / 60) as i16,
            chrono_type,
            chrono_mid,
        );
        summary = c;
        let sc = sc & 0xFF;
        contrib6 = summary[6];
        if n.wrapping_sub(inv & 0xFF) == 1 {
            day_score = sc;
            break;
        }
        weighted = weighted.wrapping_add(tot.wrapping_mul(contrib6));
        if i as u32 == (inv & 0xFF) {
            acc = Some(Acc {
                tot,
                deep,
                rem,
                ext: got_up_s,
                eff: eff_sum,
                wake: wake_s,
                tosses: restless_sum,
            });
            day_score = sc;
            continue;
        }
        let a = acc.as_mut().unwrap();
        let div_trunc = |x: u32, y: u32| if y == 0 { 0 } else { x / y };
        a.tot = a.tot.wrapping_add(tot);
        a.rem = a.rem.wrapping_add(rem);
        a.eff = a.eff.wrapping_add(eff.wrapping_mul(tot) / 60);
        let wt = a.tot / 60;
        let eff_avg = div_trunc(a.eff, wt);
        a.wake = a.wake.wrapping_add(p.wake_ups.wrapping_mul(0x1A40));
        let wake_avg = div_trunc(a.wake, wt);
        a.tosses = a.tosses.wrapping_add(p.restless.wrapping_mul(tot) / 60);
        let restless_avg = div_trunc(a.tosses, wt);
        a.ext = a.ext.wrapping_add(p.got_up.wrapping_mul(0x1A40));
        a.deep = a.deep.wrapping_add(deep);
        let ext = div_trunc(a.ext, wt);
        let (c, sc) = score_minutes(
            age,
            div60r(a.tot),
            div60r(a.deep),
            div60r(a.rem),
            eff_avg,
            div60r(abs_lat(periods[main_idx].latency)),
            wake_avg,
            restless_avg,
            ext & 0xFF,
            0xB4,
            chrono_type,
            chrono_mid,
        );
        let old = c[6];
        summary = c;
        contrib6 = div_trunc(weighted, s_total);
        summary[6] = contrib6 & 0xFF;
        day_score = (((10u32.wrapping_mul(contrib6)) as u64 * 0x51EB_851F) >> 37) as u32;
        day_score = day_score
            .wrapping_sub(old.wrapping_mul(0xCD) >> 11)
            .wrapping_add(sc & 0xFF);
    }
    if day_score == 0 {
        return DailySleep::default();
    }
    let mut contributors = summary;
    contributors[6] = contrib6 & 0xFF;
    DailySleep {
        score: day_score,
        contributors,
        total_sleep_sum: s_total,
        ..DailySleep::default()
    }
}

// ---------------------------------------------------------------------------- night record

/// The night record built from the periods.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Night {
    /// Sums of time in bed, total sleep, REM and deep sleep (s).
    pub sums: [u32; 4],
    pub highest_temp: u32,
    pub lowest_hr: u32,
    pub lowest_hr_time: u32,
    pub rmssd: u32,
}

/// First half of [`daily_readiness_stateless`]: the "main" period is the one with the largest
/// total sleep among those with `is_main != 0` (first on ties). Periods with a valid start are
/// summed; the lowest HR, highest temperature and highest RMSSD come from the periods from the
/// main one on; the lowest-HR time is that of the longest period seen so far. The highest
/// temperature is the maximum when it exceeds the main period's by more than 50, else the main
/// period's. `None` when no period has a valid start. The stateful path is the
/// same scan with the highest RMSSD starting at 1 (`rmssd_init`).
pub fn aggregate_periods(periods: &[SleepPeriod], rmssd_init: u32) -> Option<Night> {
    let n = periods.len() as u32;
    let mut found = false;
    let mut best = 0u32;
    let mut idx = u32::MAX;
    for (i, p) in periods.iter().enumerate() {
        if p.is_main != 0 {
            found = true;
            if p.total_sleep > best {
                best = p.total_sleep;
                idx = i as u32;
            }
        }
    }
    let mut v1 = [0u32; 4];
    let (mut lh_time, mut main_temp, mut max_temp, mut inv, mut best_tot) = (0u32, 0u32, 0u32, 0u32, 0u32);
    let (mut before_main, mut seen_main) = (false, false);
    let mut max_rmssd = rmssd_init;
    let mut min_hr = u32::MAX;
    for (i, p) in periods.iter().enumerate() {
        if found {
            let ismain = idx == i as u32 && p.is_main != 0;
            before_main = (!seen_main || before_main) && !ismain;
            seen_main |= ismain;
        }
        if !valid_time(p.start) {
            inv += 1;
            continue;
        }
        let fields = [p.time_in_bed, p.total_sleep, p.rem, p.deep];
        for k in 0..4 {
            v1[k] = v1[k].wrapping_add(fields[k]);
        }
        let tot = fields[1];
        if tot > best_tot {
            lh_time = p.lowest_hr_time;
            if before_main {
                best_tot = tot;
                continue;
            }
            best_tot = tot;
            main_temp = p.highest_temp;
        }
        let (temp_p, hr, rm) = (p.highest_temp, p.lowest_hr, p.rmssd);
        if !(hr >= min_hr || before_main) {
            min_hr = hr;
        }
        if !(temp_p <= max_temp || before_main) {
            max_temp = temp_p;
        }
        if !(rm <= max_rmssd || before_main) {
            max_rmssd = rm;
        }
    }
    if (inv & 0xFF) >= n {
        return None;
    }
    let temp = if max_temp > main_temp.wrapping_add(0x32) { max_temp } else { main_temp };
    Some(Night {
        sums: v1,
        highest_temp: temp,
        lowest_hr: min_hr,
        lowest_hr_time: lh_time,
        rmssd: max_rmssd,
    })
}

fn zero_readiness() -> ReadinessOutput {
    ReadinessOutput {
        score: 0,
        activity_balance: 0,
        last_day_activity: 0,
        last_night_sleep: 0,
        resting_hr: 0,
        resting_hr_time: 0,
        sleep_balance: 0,
        temperature: 0,
        hrv_balance: 0,
        sleep_regularity: 0,
        temperature_deviation: 0,
        temperature_trend_deviation: 0,
    }
}

fn with_night(sleep: &DailySleep, night: &Night) -> DailySleep {
    DailySleep {
        score: sleep.score,
        contributors: sleep.contributors,
        total_sleep_sum: night.sums[1],
        highest_temp: night.highest_temp,
        lowest_hr: night.lowest_hr,
        lowest_hr_time: night.lowest_hr_time,
        rmssd: night.rmssd,
    }
}

/// The readiness output and the sleep output with the night
/// values added. `time0` is the first word of the time argument. All zero when no
/// period is usable. `sri` is the value `sri_calculate(true)` returns from the
/// sleep-regularity state.
pub fn daily_readiness_stateless(
    sleep: &DailySleep,
    day: &DayData,
    periods: &[SleepPeriod],
    time0: i64,
    feats: &Features,
    sri: u32,
) -> (ReadinessOutput, DailySleep) {
    let Some(night) = aggregate_periods(periods, 0) else {
        return (zero_readiness(), *sleep);
    };
    let x = ReadinessInput {
        utc: time0,
        day_number: day.day_number,
        sleep_score: sleep.score,
        time_in_bed: night.sums[0],
        total_sleep: night.sums[1],
        rem: night.sums[2],
        deep: night.sums[3],
        latency: 0,
        wake_ups: 0,
        highest_temp: night.highest_temp,
        lowest_hr: night.lowest_hr,
        lowest_hr_time: night.lowest_hr_time,
        rmssd: night.rmssd,
        p40: day.user,
        prev_day: day.prev_day,
        sleep_sec_14: day.history.sleep_sec_14,
        distance_14: day.history.distance_14,
        rmssd_14: day.history.rmssd_14,
        wear_14: day.history.wear_14,
        temp_dev_3: day.history.temp_dev_3,
        hot_90: day.history.hot_90.clone(),
        baseline: day.baseline,
        cycle_day_type: day.cycle_day_type,
        rest_input: day.rest_input,
    };
    let out = readiness_calculate(&x, feats, sri, None).unwrap_or_else(zero_readiness);
    (out, with_night(sleep, &night))
}

fn sb(v: i32) -> i32 {
    (v & 0xFF) as u8 as i8 as i32
}

/// The stateful (V1) path: the same night record, but
/// `recovery_run` runs on the persistent state `s` (modified in place, with baseline updates
/// when `upd`) and the rest-mode block `rm`. The output's temperature deviation and trend are
/// not computed (0 here). `j` is the baseline sleep-time input of
/// `recovery_run`, `j1` the state day word and `j2` the baseline age of the temperature update.
#[allow(clippy::too_many_arguments)]
pub fn daily_readiness_stateful(
    sleep: &DailySleep,
    prev_day: &[u32; 8],
    periods: &[SleepPeriod],
    s: &mut State,
    rm: &RestMode,
    j: u32,
    j1: u32,
    j2: u32,
    upd: bool,
    time0: i64,
    feats: &Features,
    sri: u32,
) -> (ReadinessOutput, DailySleep) {
    let Some(night) = aggregate_periods(periods, 1) else {
        return (zero_readiness(), *sleep);
    };
    let [tib, total, rem, deep] = night.sums;
    let ds = deep.wrapping_add(rem);
    let ss = SleepSummary {
        awake: if tib >= total {
            ((tib - total) / 30) as i64
        } else {
            0
        },
        rem: (rem / 30) as i64,
        light: if total >= ds {
            ((total - ds) / 30) as i64
        } else {
            0
        },
        deep: (deep / 30) as i64,
        extra: (night.lowest_hr_time / 30) as i64,
        b0a: night.lowest_hr as u8,
        sleep_score: sleep.score as u8,
        b0c: 0,
        b0d: 0,
    };
    let hours = ((tib as f32 + 1800.0) / 3600.0) as i32;
    s.b[0x65] = prev_day[4] as u8;
    s.set16(0x20, (prev_day[1] >> 3) as i32);
    s.set16(0x3E, prev_day[3] as i32);
    let f = (night.rmssd as f64).log2() as f32;
    let (summary, _) = recovery_run(
        s,
        None,
        Some(&ss),
        rm,
        night.highest_temp,
        hours,
        f,
        j,
        j1,
        j2,
        upd,
        Some((night.lowest_hr, night.lowest_hr_time)),
        time0,
        feats,
        sri,
        None,
    );
    let out = ReadinessOutput {
        score: sb(summary[0]),
        activity_balance: sb(summary[4]),
        last_day_activity: sb(summary[3]),
        last_night_sleep: sb(summary[1]),
        resting_hr: sb(summary[5]),
        resting_hr_time: sb(summary[7]),
        sleep_balance: sb(summary[2]),
        temperature: sb(summary[6]),
        hrv_balance: sb(summary[8]),
        sleep_regularity: if summary[9] == 0x80 {
            -1
        } else {
            sb(summary[9])
        },
        temperature_deviation: 0,
        temperature_trend_deviation: 0,
    };
    (out, with_night(sleep, &night))
}

// ---------------------------------------------------------------------------- daily outputs

/// Tail of [`daily_outputs_stateless`]: the running maximum of the prefix sleep
/// scores, lowered to a later score when that prefix ends in a main period (`is_main == 1`).
pub fn final_sleep_score(prefix_scores: &[u32], periods: &[SleepPeriod]) -> u32 {
    let mut cur = 0u32;
    for (&s, p) in prefix_scores.iter().zip(periods) {
        let mut nxt = s.max(cur);
        if cur > s && p.is_main == 1 {
            nxt = s;
        }
        cur = nxt;
    }
    cur
}

/// Outputs of [`daily_outputs_stateless`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct DailyOutputs {
    pub sleep: DailySleep,
    pub readiness: ReadinessOutput,
    /// Per prefix of the periods.
    pub sleep_scores: Vec<u32>,
    pub readiness_scores: Vec<i32>,
    /// Score minus the previous prefix's (0 for the first), as a u32.
    pub sleep_deltas: Vec<u32>,
    pub readiness_deltas: Vec<u32>,
    /// Per prefix: total sleep, deep, REM, HRV balance, resting HR, recovery index, body
    /// temperature.
    pub v2_inputs: Vec<[u32; 7]>,
    /// (sleep day UTC, second time word), copied to the first 16 bytes of both outputs.
    pub time: (i64, i64),
}

/// The input validation of [`daily_outputs_stateless`]: `false` when the input is rejected
/// (return code 13).
pub fn check_inputs(day: &DayData, periods: &[SleepPeriod]) -> bool {
    let (Some(pd), Some(_)) = (&day.prev_day, &day.user) else {
        return false;
    };
    !periods.is_empty()
        && periods.iter().all(|p| p.total_sleep != 0)
        && periods.iter().any(|p| p.is_main == 1)
        && pd[1] <= 5_000_000
        && pd[2] <= 1500
        && pd[3] <= 1500
        && pd[4] <= 1500
}

/// Daily outputs from the day's periods. `chrono` is (type, ideal midpoint in seconds) or
/// `None`; `tz_word` is the second time word. `None` when the input is rejected (see
/// [`check_inputs`]).
pub fn daily_outputs_stateless(
    sleep_day_utc: i64,
    tz_word: i64,
    day: &DayData,
    periods: &[SleepPeriod],
    chrono: Option<(u8, i32)>,
    feats: &Features,
    sri: u32,
) -> Option<DailyOutputs> {
    if !check_inputs(day, periods) {
        return None;
    }
    let age = day.user.map_or(0, |u| u.1);
    let t0 = if sleep_day_utc > 86400 {
        sleep_day_utc - 86400
    } else {
        sleep_day_utc
    };
    let (ctype, cmid) = chrono.map_or((0xFF, 0), |(t, sec)| (t, sec / 60));
    let mut res = DailyOutputs {
        sleep: DailySleep::default(),
        readiness: zero_readiness(),
        sleep_scores: vec![],
        readiness_scores: vec![],
        sleep_deltas: vec![],
        readiness_deltas: vec![],
        v2_inputs: vec![],
        time: (sleep_day_utc, tz_word),
    };
    let (mut prev_s, mut prev_r) = (0u32, 0i32);
    let mut last = (DailySleep::default(), zero_readiness());
    for k in 1..=periods.len() {
        let sl = get_daily_sleep(age, ctype, cmid, &periods[..k]);
        let (ro, sl) = daily_readiness_stateless(&sl, day, &periods[..k], t0, feats, sri);
        res.sleep_scores.push(sl.score);
        res.readiness_scores.push(ro.score);
        res.sleep_deltas.push(if k > 1 {
            sl.score.wrapping_sub(prev_s)
        } else {
            0
        });
        res.readiness_deltas.push(if k > 1 {
            (ro.score.wrapping_sub(prev_r)) as u32
        } else {
            0
        });
        res.v2_inputs.push([
            sl.contributors[0],
            sl.contributors[1],
            sl.contributors[2],
            ro.hrv_balance as u32,
            ro.resting_hr as u32,
            ro.resting_hr_time as u32,
            ro.temperature as u32,
        ]);
        prev_s = sl.score;
        prev_r = ro.score;
        last = (sl, ro);
    }
    let (mut sl, ro) = last;
    sl.score = final_sleep_score(&res.sleep_scores, periods);
    res.sleep = sl;
    res.readiness = ro;
    Some(res)
}

/// The seven prefix scores of
/// [`DailyOutputs::v2_inputs`] become the v2 scores, with 0 or less mapped to missing. The
/// sessions' hypnograms, the 90-day SFI and breathing-rate histories and the age are supplied
/// by the caller.
pub fn v2_input(
    prefix: &[u32; 7],
    sessions: Vec<Session>,
    sfi_history: Option<Vec<f32>>,
    br_history: Option<Vec<f32>>,
    age: u32,
) -> ReadinessV2Input {
    let m = |v: u32| if (v as i32) > 0 { v } else { MISSING };
    ReadinessV2Input {
        total_sleep: m(prefix[0]),
        deep_sleep: m(prefix[1]),
        rem_sleep: m(prefix[2]),
        hrv_balance: m(prefix[3]),
        resting_hr: m(prefix[4]),
        recovery_index: m(prefix[5]),
        body_temp: m(prefix[6]),
        sessions,
        sfi_history,
        br_history,
        age,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn hex<const N: usize>(s: &str) -> [u8; N] {
        let mut out = [0u8; N];
        for (i, o) in out.iter_mut().enumerate() {
            *o = u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap();
        }
        out
    }

    fn feats(f: [bool; 5]) -> Features {
        Features {
            hrv_in_readiness: f[0],
            rest_mode: f[1],
            sleep_regularity: f[2],
            freeze_baseline: f[3],
            athletes: f[4],
        }
    }

    fn ro_array(o: &ReadinessOutput) -> [i32; 12] {
        [
            o.score,
            o.last_night_sleep,
            o.sleep_balance,
            o.last_day_activity,
            o.activity_balance,
            o.resting_hr,
            o.resting_hr_time,
            o.temperature,
            o.hrv_balance,
            o.sleep_regularity,
            o.temperature_deviation,
            o.temperature_trend_deviation,
        ]
    }

    fn sleep_array(s: &DailySleep) -> [u32; 13] {
        let c = s.contributors;
        [
            s.score,
            c[0],
            c[1],
            c[2],
            c[3],
            c[4],
            c[5],
            c[6],
            s.total_sleep_sum,
            s.highest_temp,
            s.lowest_hr,
            s.lowest_hr_time,
            s.rmssd,
        ]
    }

    #[test]
    fn prefix_scores_map_to_v2_scores() {
        let x = v2_input(&[0, 5, 100, 0xFFFF_FFFF, 1, 0, 70], vec![], None, None, 30);
        assert_eq!(
            [
                x.total_sleep,
                x.deep_sleep,
                x.rem_sleep,
                x.hrv_balance,
                x.resting_hr,
                x.recovery_index,
                x.body_temp
            ],
            [MISSING, 5, 100, MISSING, 1, MISSING, 70]
        );
    }

    macro_rules! vector_tests {
        () => {
            #[test]
            fn get_daily_sleep_matches_reference() {
                for (i, (age, ct, cm, ps, want)) in sleep_vectors().into_iter().enumerate() {
                    let got = get_daily_sleep(age, ct, cm, &ps);
                    assert_eq!(&sleep_array(&got)[..9], &want[..], "case {i}");
                }
            }

            #[test]
            fn stateless_matches_reference() {
                for (i, c) in stateless_vectors().into_iter().enumerate() {
                    let sleep = DailySleep {
                        score: c.sleep_score,
                        ..DailySleep::default()
                    };
                    let (ro, so) = daily_readiness_stateless(
                        &sleep,
                        &c.day,
                        &c.periods,
                        c.time0,
                        &feats(c.feats),
                        c.sri,
                    );
                    if let Some((want_r, want_s)) = c.want {
                        assert_eq!(ro_array(&ro), want_r, "case {i} readiness");
                        assert_eq!(
                            [
                                so.total_sleep_sum,
                                so.highest_temp,
                                so.lowest_hr,
                                so.lowest_hr_time,
                                so.rmssd
                            ],
                            want_s,
                            "case {i} sleep"
                        );
                    } else {
                        assert_eq!(ro_array(&ro), [0; 12], "case {i} unusable periods");
                    }
                }
            }

            #[test]
            fn stateful_matches_reference() {
                for (i, c) in stateful_vectors().into_iter().enumerate() {
                    let mut st = State { b: hex(c.state) };
                    let sleep = DailySleep {
                        score: c.sleep_score,
                        ..DailySleep::default()
                    };
                    let rm = RestMode {
                        state: c.rest[0],
                        total: c.rest[1],
                        remaining: c.rest[2],
                    };
                    let (ro, so) = daily_readiness_stateful(
                        &sleep,
                        &c.prev_day,
                        &c.periods,
                        &mut st,
                        &rm,
                        c.j,
                        c.j1,
                        c.j2,
                        c.upd,
                        c.time0,
                        &feats(c.feats),
                        c.sri,
                    );
                    if let Some((want_r, want_s, want_state)) = c.want {
                        assert_eq!(&ro_array(&ro)[..10], &want_r[..], "case {i} readiness");
                        assert_eq!(
                            [
                                so.total_sleep_sum,
                                so.highest_temp,
                                so.lowest_hr,
                                so.lowest_hr_time,
                                so.rmssd
                            ],
                            want_s,
                            "case {i} sleep"
                        );
                        assert_eq!(st.b, hex::<{ State::SIZE }>(want_state), "case {i} state");
                    } else {
                        assert_eq!(ro_array(&ro), [0; 12], "case {i} unusable periods");
                    }
                }
            }

            #[test]
            fn daily_outputs_match_reference() {
                for (i, c) in daily_vectors().into_iter().enumerate() {
                    let got = daily_outputs_stateless(
                        c.day_utc,
                        c.tz_word,
                        &c.day,
                        &c.periods,
                        c.chrono,
                        &feats(c.feats),
                        c.sri,
                    );
                    match (got, c.want) {
                        (None, None) => {}
                        (Some(g), Some(w)) => {
                            assert_eq!(ro_array(&g.readiness), w.readiness, "case {i} readiness");
                            assert_eq!(sleep_array(&g.sleep), w.sleep, "case {i} sleep");
                            assert_eq!(g.sleep_scores, w.sleep_scores, "case {i}");
                            assert_eq!(g.readiness_scores, w.readiness_scores, "case {i}");
                            assert_eq!(g.sleep_deltas, w.sleep_deltas, "case {i}");
                            assert_eq!(g.readiness_deltas, w.readiness_deltas, "case {i}");
                            assert_eq!(g.v2_inputs, w.v2_inputs, "case {i}");
                            assert_eq!(g.time, (c.day_utc, c.tz_word), "case {i}");
                        }
                        (g, w) => panic!("case {i}: port {:?} reference {:?}", g.is_some(), w.is_some()),
                    }
                }
            }
        };
    }

    mod python_port {
        use super::*;
        include!("vectors/readiness_inputs.rs");
        vector_tests!();
    }

}
